-- Inquiries a searcher chose to send to the agency that manages a property
-- (CONTEXT.md, Inquiry). The brief is exactly what the searcher saw before
-- sending; nothing else they declared or searched is stored.
CREATE TABLE listing_inquiries (
    -- Generated by the browser once per deliberate send, so a retried send
    -- cannot deliver the same inquiry twice.
    id         uuid PRIMARY KEY,
    listing_id bigint NOT NULL REFERENCES listings (id) ON DELETE CASCADE,
    brief      jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX listing_inquiries_listing_idx ON listing_inquiries (listing_id, created_at DESC);
